export const RUNTIME_LOOP = "async function init() {\n  await loadAssets();\n  buildScene();\n  buildCustomUI();\n  applyBaseUI();\n  setupPlayEntities();\n\n  const startScreen = document.getElementById('startScreen');\n  startScreen.addEventListener('click', () => {\n    startScreen.style.display = 'none';\n    if (activePlayerObj) {\n      nodeRuntime.enableInput(renderer.domElement);\n      try { renderer.domElement.requestPointerLock?.(); } catch (err) {}\n    } else {\n      enableFallbackFPS();\n      try { renderer.domElement.requestPointerLock?.(); } catch (err) {}\n    }\n    if (isLikelyMobile) activateMobileUI();\n    nodeRuntime.triggerEvent('OnStart', null);\n  });\n\n  document.body.addEventListener('click', (e) => {\n    if (!inspectActive && !document.pointerLockElement && startScreen.style.display === 'none') {\n      if (!e.target.closest('.mobile-joystick-area, .mobile-look-area, .mobile-interact-btn, .inspect-overlay')) {\n        try { renderer.domElement.requestPointerLock?.(); } catch (err) {}\n      }\n    }\n  });\n\n  window.addEventListener('keydown', (e) => {\n    if ((e.code === 'KeyE' || e.key?.toLowerCase() === 'e') && !inspectActive) {\n      tryInteract();\n    }\n  });\n\n  const clock = new THREE.Clock();\n  function loop() {\n    requestAnimationFrame(loop);\n    const dt = Math.min(clock.getDelta(), 0.1);\n\n    if (activePlayerObj) {\n      nodeRuntime.update(dt);\n      updateInteraction();\n\n      activePlayerObj.updateMatrixWorld(true);\n      const childCam = activePlayerObj.children.find(c => (c.isCamera || c.userData?.type === 'camera') && !c.userData?.isGizmo)\n        || sceneManagerAdapter.getChildren(activePlayerObj.userData.id).find(c => (c.isCamera || c.userData?.type === 'camera') && !c.userData?.isGizmo);\n\n      if (childCam) {\n        childCam.updateMatrixWorld(true);\n        const worldPos = new THREE.Vector3();\n        const worldQuat = new THREE.Quaternion();\n        childCam.getWorldPosition(worldPos);\n        childCam.getWorldQuaternion(worldQuat);\n        camera.position.copy(worldPos);\n        camera.quaternion.copy(worldQuat);\n      }\n\n      const radius = activePlayerObj.userData?.playerController?.playerRadius || 0.3;\n      collisionAdapter.checkTriggers(camera.position, radius);\n    } else if (activeCameraObj) {\n      nodeRuntime.update(dt);\n      updateInteraction();\n\n      activeCameraObj.updateMatrixWorld(true);\n      const worldPos = new THREE.Vector3();\n      const worldQuat = new THREE.Quaternion();\n      activeCameraObj.getWorldPosition(worldPos);\n      activeCameraObj.getWorldQuaternion(worldQuat);\n      camera.position.copy(worldPos);\n      camera.quaternion.copy(worldQuat);\n\n      collisionAdapter.checkTriggers(camera.position, 0.5);\n    } else {\n      updateFallbackFPS(dt);\n      nodeRuntime.update(dt);\n      updateInteraction();\n    }\n\n    renderer.render(scene, camera);\n    if (inspectActive) iRenderer.render(inspectScene, iCam);\n  }\n  loop();\n}\n\ninit();\n";
export const EXPORT_SHELL = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no\">\n<title>Exported Scene ThreeJSINT</title>\n<style>\n/* __EXPORT_CSS__ */\n</style>\n</head>\n<body>\n<div id=\"container\"></div>\n<div class=\"custom-ui-layer\" id=\"customUILayer\"></div>\n<div class=\"start-screen\" id=\"startScreen\"><span>Click to Start</span></div>\n\n<script type=\"importmap\">\n{\n  \"imports\": {\n    \"three\": \"https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js\",\n    \"three/addons/\": \"https://cdn.jsdelivr.net/npm/three@0.170.0/examples/jsm/\"\n  }\n}\n</script>\n<script type=\"module\">\nimport * as THREE from 'three';\nimport { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';\n\nconst SCENE_DATA = /* __SCENE_DATA__ */ {};\nconst ASSETS_DATA = /* __ASSETS_DATA__ */ {};\nconst UI_DATA = /* __UI_DATA__ */ {};\nconst NODE_DATA = /* __NODE_DATA__ */ {};\n\n/* __EXPORT_RUNTIME_CORE__ */\n\n/* __EXPORT_RUNTIME_SCENE__ */\n\n/* __EXPORT_RUNTIME_UI__ */\n\n/* __RUNTIME_CLASS_SOURCE__ */\n\n/* __EXPORT_RUNTIME_PHYSICS__ */\n\n/* __EXPORT_RUNTIME_CONTROLLERS__ */\n\n/* __EXPORT_RUNTIME_LOOP__ */\n</script>\n</body>\n</html>\n";

export function generateExportHTML(sceneData, assetsData, uiData, nodeGraphData, runtimeClassSource) {
  let html = EXPORT_SHELL;
  html = html.replace('/* __EXPORT_CSS__ */', EXPORT_CSS);
  html = html.replace('/* __SCENE_DATA__ */ {}', JSON.stringify(sceneData));
  html = html.replace('/* __ASSETS_DATA__ */ {}', JSON.stringify(assetsData));
  html = html.replace('/* __UI_DATA__ */ {}', JSON.stringify(uiData || {}));
  html = html.replace('/* __NODE_DATA__ */ {}', JSON.stringify(nodeGraphData || {}));
  html = html.replace('/* __EXPORT_RUNTIME_CORE__ */', RUNTIME_CORE);
  html = html.replace('/* __EXPORT_RUNTIME_SCENE__ */', RUNTIME_SCENE);
  html = html.replace('/* __EXPORT_RUNTIME_UI__ */', RUNTIME_UI);
  html = html.replace('/* __RUNTIME_CLASS_SOURCE__ */', runtimeClassSource);
  html = html.replace('/* __EXPORT_RUNTIME_PHYSICS__ */', RUNTIME_PHYSICS);
  html = html.replace('/* __EXPORT_RUNTIME_CONTROLLERS__ */', RUNTIME_CONTROLLERS);
  html = html.replace('/* __EXPORT_RUNTIME_LOOP__ */', RUNTIME_LOOP);
  return html;
}
